SELECT c.*, o.order_no AS order_no, o.pay_amount AS pay_amount, u.nickname AS student_name, s.name AS stall_name FROM complaint c JOIN order_info o ON o.id = c.order_id JOIN `user` u ON u.id = c.student_user_id JOIN stall s ON s.id = c.stall_id
c.status = #{status}
ORDER BY c.status ASC, c.create_time DESC
